import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { OrderService } from '../../services/order.service';
import { Order } from '../../models/order';

@Component({
  selector: 'app-my-orders',
  templateUrl: './my-orders.component.html',
  styleUrls: ['./my-orders.component.css']
})
export class MyOrdersComponent implements OnInit {
  orders: Order[] = [];
  loading = false;
  error: string | null = null;

  constructor(private orderService: OrderService, private router: Router) {}

  ngOnInit(): void {
    this.loadOrders();
  }

  loadOrders(): void {
    this.loading = true;
    this.error = null;
    this.orderService.getMyOrders().then((data: Order[] | undefined) => {
      this.orders = data || [];
    }).catch(err => {
      this.error = err?.error?.error || 'Failed to load orders';
    }).finally(() => {
      this.loading = false;
    });
  }

  goBack(): void {
    this.router.navigate(['/packages']);
  }
}
<div class="min-h-screen bg-gray-50">
  <header class="bg-white shadow-sm">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
      <div class="flex items-center justify-between">
        <button (click)="goBack()" class="inline-flex items-center text-sm text-gray-600 hover:text-primary">
          <svg class="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
          </svg>
          Back to Packages
        </button>
        <h1 class="text-lg font-bold text-gray-900">My Orders</h1>
      </div>
    </div>
  </header>

  <main class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
    <div *ngIf="loading" class="flex justify-center py-16">
      <div class="inline-block animate-spin rounded-full h-6 w-6 border-b-2 border-primary"></div>
    </div>

    <div *ngIf="!loading && error" class="text-center py-16">
      <div class="text-red-500 mb-3">
        <svg class="w-6 h-6 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
      </div>
      <p class="text-sm text-red-600">{{ error }}</p>
      <button (click)="loadOrders()" class="mt-4 bg-primary text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-primary-dark transition-colors">Retry</button>
    </div>

    <div *ngIf="!loading && !error && orders.length === 0" class="text-center py-16">
      <svg class="w-8 h-8 mx-auto text-gray-300 mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
      </svg>
      <p class="text-sm text-gray-600 mb-1">No orders yet</p>
      <p class="text-xs text-gray-500">Place your first order from the software packages page.</p>
    </div>

    <div *ngIf="!loading && !error && orders.length > 0" class="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
      <div class="px-6 py-4 border-b border-gray-200 bg-gray-50">
        <h2 class="text-sm font-bold text-gray-700 uppercase tracking-wider">Order History</h2>
      </div>
      <table class="w-full text-left divide-y divide-gray-200">
        <thead>
          <tr>
            <th class="px-6 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">Package</th>
            <th class="px-6 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">Quantity</th>
            <th class="px-6 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">Total</th>
            <th class="px-6 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
            <th class="px-6 py-3 text-xs font-medium text-gray-500 uppercase tracking-wider">Date</th>
          </tr>
        </thead>
        <tbody class="divide-y divide-gray-100 bg-white">
          <tr *ngFor="let order of orders" class="hover:bg-gray-50 transition-colors">
            <td class="px-6 py-4">
              <div class="flex items-center gap-3">
                <img [src]="order.thumbnail || 'https://via.placeholder.com/40'" [alt]="order.title" class="w-8 h-8 object-cover rounded" />
                <div class="text-sm text-gray-900 font-medium">{{ order.title }}</div>
              </div>
            </td>
            <td class="px-6 py-4 text-sm text-gray-700">{{ order.quantity }}</td>
            <td class="px-6 py-4 text-sm font-medium text-gray-700">{{ order.totalPrice | currency:'USD' }}</td>
            <td class="px-6 py-4">
              <span class="inline-flex items-center px-2 py-1 rounded-full text-[10px] font-medium" [class.bg-yellow-100]="order.status === 'PENDING'" [class.text-yellow-700]="order.status === 'PENDING'" [class.bg-green-100]="order.status !== 'PENDING'" [class.text-green-700]="order.status !== 'PENDING'">{{ order.status }}</span>
            </td>
            <td class="px-6 py-4 text-sm text-gray-600">{{ order.createdAt | date:'mediumDate' }}</td>
          </tr>
        </tbody>
      </table>
    </div>
  </main>
</div>
